# ---- scans named in the prompt (cote 140-2), union with BACKGROUND's list
def named_scans(text):
    s = set()
    for m in re.finditer(r"\bscans?\s+(\d+(?:\s*[–-]\s*\d+)?(?:\s*(?:,\s*and|,|and)\s*\d+(?:\s*[–-]\s*\d+)?)*)", text):
        for a, b in re.findall(r"(\d+)(?:\s*[–-]\s*(\d+))?", m.group(1)):
            a = int(a); b = int(b) if b else a
            s.update(range(a, b + 1))
    s.update({281, 285, 288})   # cited as bare "(281)", "(285)", "(288)" in item 5
    return s
OLDLIST = "53–54, 62, 69, 84, 101–102, 118, 136–139, 148, 155–160, 179, 197–203, 270–271, 281, 285, 288–294, 304, 353"
old = set()
for a, b in re.findall(r"(\d+)(?:–(\d+))?", OLDLIST):
    a = int(a); b = int(b) if b else a; old.update(range(a, b + 1))
S = named_scans(t) | old
def ranges(s):
    s = sorted(s); out = []; i = 0
    while i < len(s):
        j = i
        while j + 1 < len(s) and s[j + 1] == s[j] + 1: j += 1
        out.append(str(s[i]) if i == j else "%d–%d" % (s[i], s[j])); i = j + 1
    return ", ".join(out)
print("scans named in PROMPT.md:", ranges(named_scans(t)))
print("added to BACKGROUND list:", ranges(S - old))
print("all scans (%d):" % len(S), ranges(S))

